			function comboValidation(poData1, poData2) {
			    
			    /* poData1 : 호출한 combobox ID
			     * poData2 : 선택 ITEM
			     */
			    var bRtnFlag = true;

			    if (poData1 == "cmbYngbgsSeNo" && poData2 != null) {
			        bRtnFlag = yngbgsSeValidChk(cpr.utils.Util.toString(poData2));
			    }

			    return bRtnFlag;
			    
			}
			exports.comboValidation = comboValidation;

			function yngbgsSeValidChk(sYngbgsSeNo) {
			    var returnVal = "";    

			    returnVal = sYngbgsSeNo;

			    if (returnVal.indexOf("01") >= 0 ) {
			        if (returnVal.indexOf("05") >= 0) {
			            util.Msg.alert(app, "학교밖청소년, 재학생은 동시 선택할 수 없습니다.");
			            return false;
			        }
			    }    
			    
			    return true;
			}

